以下关于完全二叉树的代码描述，正确的是（ ）。
```cpp
bool isCompleteTree(TreeNode* root) {
    if (root == nullptr) return true;
    queue<TreeNode*> q; q.push(root);
    bool hasNull = false;
    while (!q.empty()) {
        TreeNode* node = q.front(); q.pop();
        if (node == nullptr) hasNull = true;
        else {
            if (hasNull) return false;
            q.push(node->left); q.push(node->right);
        }
    }
    return true;
}
```

以下代码实现了二叉排序树的哪种操作？
```cpp
TreeNode* op(TreeNode* root, int val) {
    if (root == nullptr) return new TreeNode(val);
    if (val < root->val) root->left = op(root->left, val);
    else root->right = op(root->right, val);
    return root;
}
```

